const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

// 1. Extract Token from Authorization header (Bearer <token>) or body/query
let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      valid: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Please log in again."
    }
  }];
}

const callerId = String(claims.sub).trim();
const callerRole = String(claims.role || 'EMPLOYEE').toUpperCase().trim();
const callerName = String(claims.name || claims.sub).trim();

const webhookNode = $('Webhook - POST /leave-list').first().json || {};
const body = webhookNode.body || {};

const action = String(body.action || 'LIST').toUpperCase().trim();
const year = parseInt(body.year || new Date().getFullYear(), 10);

// Admin actions: APPROVE, REJECT, or RESET/PENDING
if (action === 'APPROVE' || action === 'REJECT' || action === 'RESET' || action === 'PENDING') {
  if (callerRole !== 'ADMIN') {
    return [{
      json: {
        valid: false,
        statusCode: 403,
        error: "Forbidden. Only HR / Admin accounts are authorized to approve or reject leave requests."
      }
    }];
  }
  const requestId = String(body.requestId || '').trim();
  if (!requestId) {
    return [{
      json: {
        valid: false,
        statusCode: 400,
        error: "Leave requestId is required for approval/rejection."
      }
    }];
  }
  const reviewComment = String(body.comment || (action === 'APPROVE' ? 'Approved by HR Operations.' : (action === 'REJECT' ? 'Rejected as per company operational guidelines.' : 'Reopened for review.'))).trim();
  const notifId = `notif-${Date.now()}-${callerId}`;

  return [{
    json: {
      valid: true,
      isActionReview: true,
      action: action,
      requestId: requestId,
      callerId: callerId,
      callerName: callerName,
      comment: reviewComment,
      escapedComment: reviewComment.replace(/'/g, "''"),
      notifId: notifId
    }
  }];
}

// Listing action
let targetEmployeeId = callerId;
if (callerRole === 'ADMIN' && body.employeeId && body.employeeId !== 'ALL') {
  targetEmployeeId = String(body.employeeId).trim();
} else if (callerRole === 'ADMIN' || body.all === true || body.all === 'true' || body.targetEmployeeId === 'ALL') {
  targetEmployeeId = 'ALL';
}

const statusFilter = String(body.status || body.statusFilter || 'ALL').toUpperCase().trim();

return [{
  json: {
    valid: true,
    isActionReview: false,
    action: 'LIST',
    callerId: callerId,
    callerRole: callerRole,
    targetEmployeeId: targetEmployeeId,
    statusFilter: statusFilter,
    year: year
  }
}];

const items = $input.all();
const row = (items.length > 0 && items[0].json) ? items[0].json : {};
const req = row.leave_request;

if (!req) {
  return [{
    json: {
      success: false,
      statusCode: 404,
      error: "Leave request not found or failed to update."
    }
  }];
}

return [{
  json: {
    success: true,
    statusCode: 200,
    message: `Leave request successfully updated to ${req.status}.`,
    request: req,
    balance: row.updated_balance || null
  }
}];

const items = $input.all();
const row = (items.length > 0 && items[0].json) ? items[0].json : {};

const balances = Array.isArray(row.balances) ? row.balances : [];
const requests = Array.isArray(row.requests) ? row.requests : [];

return [{
  json: {
    success: true,
    statusCode: 200,
    balances: balances,
    requests: requests,
    totalRequests: requests.length,
    pendingCount: requests.filter(r => r.status === 'PENDING').length,
    approvedCount: requests.filter(r => r.status === 'APPROVED').length,
    rejectedCount: requests.filter(r => r.status === 'REJECTED').length
  }
}];

